import 'package:flutter/material.dart';import '../../../core/network/football_repository.dart';
class NewsScreen extends StatefulWidget{const NewsScreen({super.key});@override State<NewsScreen> createState()=>_NewsScreenState();}
class _NewsScreenState extends State<NewsScreen>{final repo=FootballRepository();late Future<List<dynamic>> future;@override void initState(){super.initState();future=repo.personalizedNews();}Future<void> reload()async{setState(()=>future=repo.personalizedNews());await future;}@override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:RefreshIndicator(onRefresh:reload,child:FutureBuilder<List<dynamic>>(future:future,builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());if(s.hasError)return ListView(children:[const SizedBox(height:180),Center(child:Text('Unable to load news')),TextButton(onPressed:reload,child:const Text('Retry'))]);final items=s.data??[];return ListView(padding:const EdgeInsets.all(16),children:[const Text('الأخبار',style:TextStyle(fontSize:28,fontWeight:FontWeight.w900)),const SizedBox(height:14),const Text('For you • Latest • Breaking • Transfers',style:TextStyle(fontWeight:FontWeight.w600)),const SizedBox(height:14),if(items.isEmpty)const Padding(padding:EdgeInsets.all(40),child:Center(child:Text('No published stories yet.'))),...items.map((n)=>Card(child:ListTile(contentPadding:const EdgeInsets.all(12),leading:n['is_breaking']==true?const CircleAvatar(child:Icon(Icons.bolt)):const CircleAvatar(child:Icon(Icons.article_outlined)),title:Text('${n['title']??''}',maxLines:3,overflow:TextOverflow.ellipsis),subtitle:Text('${n['category']??''} • ${n['author_name']??''}'),onTap:(){final id=n['id'];if(id is int)repo.articleSignal(id,'open');})))];})))));}
